package com.reactur.backend.enums;

/**
 * Represents the lifecycle state of a 3D structure associated with a reactant.
 * This flag tracks the structure from its initial creation (via external API or manual upload)
 * through user verification to its final active or rejected state.
 */
public enum StructureFlag {
    /**
     * The structure generation job has been triggered via the external API
     * and is currently in progress or queued. Awaiting polling to complete.
     */
    PENDING,

    /**
     * The structure has been successfully generated by the external API and saved
     * to the database, but is awaiting manual selection/verification by a user.
     */
    READY,

    /**
     * This structure is the single valid, verified, and currently used 3D representation
     * for the associated reactant. Manually uploaded structures default to this state.
     */
    ACTIVE,

    /**
     * This structure was generated but not selected by the user, or it was replaced
     * by another structure that was subsequently marked as ACTIVE.
     */
    REJECTED,

    /**
     * The external API failed to generate the structure, returned an error,
     * or the retrieved structure data was invalid.
     */
    FAILED
}
